/*
 * ============================================================================
 *  Look-and-Say Sequence Generator (Morris Number Sequence)
 * ============================================================================
 *
 *  The Look-and-Say sequence begins with "1" and each subsequent term is
 *  generated by reading the previous term aloud — counting consecutive runs
 *  of identical digits:
 *
 *    1       -> "one 1"       -> 11
 *    11      -> "two 1s"      -> 21
 *    21      -> "one 2, one 1"-> 1211
 *    1211    -> "one 1, one 2, two 1s" -> 111221
 *    111221  -> "three 1s, two 2s, one 1" -> 312211
 *
 *  Properties (Conway's analysis):
 *  - The length of consecutive terms grows by a factor of approximately
 *    lambda = 1.303577... (Conway's constant).
 *  - Starting from any digit d (1-9), the sequence never produces a digit > 3
 *    (except d itself in the first term).
 *  - The sequence is related to Conway's "audioactive decay" — each term
 *    eventually decomposes into 92 "elements" (atomic strings).
 *
 *  Time Complexity:  O(L) per term generation, where L is the length of the
 *                    previous term.
 *  Space Complexity: O(L) for storing terms.
 * ============================================================================
 */

#include <iostream>
#include <string>
#include <vector>
#include <iomanip>
#include <cstdint>

namespace look_and_say {

std::string nextTerm(const std::string& current) {
    std::string result;
    int n = static_cast<int>(current.size());
    int i = 0;

    while (i < n) {
        char digit = current[i];
        int count = 1;
        while (i + count < n && current[i + count] == digit) {
            ++count;
        }
        result += std::to_string(count);
        result += digit;
        i += count;
    }

    return result;
}

std::vector<std::string> generateSequence(int numTerms, const std::string& seed = "1") {
    std::vector<std::string> sequence;
    sequence.reserve(numTerms);
    sequence.push_back(seed);

    for (int i = 1; i < numTerms; ++i) {
        sequence.push_back(nextTerm(sequence.back()));
    }

    return sequence;
}

/* Count occurrences of each digit in a term */
void digitFrequency(const std::string& term, int freq[10]) {
    for (int i = 0; i < 10; ++i) freq[i] = 0;
    for (char c : term) {
        freq[c - '0']++;
    }
}

} // namespace look_and_say

int main() {
    std::cout << "========================================================\n";
    std::cout << "  Look-and-Say Sequence Generator\n";
    std::cout << "========================================================\n\n";

    int numTerms = 15;
    auto sequence = look_and_say::generateSequence(numTerms);

    std::cout << "First " << numTerms << " terms of the Look-and-Say sequence:\n\n";

    for (int i = 0; i < numTerms; ++i) {
        std::cout << "  Term " << std::setw(2) << (i + 1) << " (len "
                  << std::setw(5) << sequence[i].size() << "): ";
        if (sequence[i].size() <= 60) {
            std::cout << sequence[i];
        } else {
            std::cout << sequence[i].substr(0, 50) << "... (truncated)";
        }
        std::cout << "\n";
    }

    /* Growth rate analysis */
    std::cout << "\nGrowth Rate Analysis (ratio of consecutive lengths):\n";
    std::cout << std::setw(8) << "Term" << std::setw(10) << "Length"
              << std::setw(14) << "Ratio" << "\n";
    std::cout << "--------------------------------\n";

    for (int i = 0; i < numTerms; ++i) {
        double ratio = (i > 0)
            ? static_cast<double>(sequence[i].size()) / static_cast<double>(sequence[i - 1].size())
            : 0.0;
        std::cout << std::setw(8) << (i + 1) << std::setw(10) << sequence[i].size();
        if (i > 0) {
            std::cout << std::setw(14) << std::fixed << std::setprecision(6) << ratio;
        } else {
            std::cout << std::setw(14) << "---";
        }
        std::cout << "\n";
    }
    std::cout << "\n  Conway's constant (limit ratio) ~ 1.303577...\n";

    /* Digit frequency of a middle term */
    int freqTerm = 10;
    int freq[10];
    look_and_say::digitFrequency(sequence[freqTerm - 1], freq);
    std::cout << "\nDigit frequency in term " << freqTerm << " (length "
              << sequence[freqTerm - 1].size() << "):\n";
    for (int d = 0; d <= 9; ++d) {
        if (freq[d] > 0) {
            std::cout << "  Digit " << d << ": " << freq[d] << "\n";
        }
    }

    /* Different seed */
    std::cout << "\nLook-and-Say starting from seed \"2\":\n";
    auto seq2 = look_and_say::generateSequence(8, "2");
    for (int i = 0; i < 8; ++i) {
        std::cout << "  Term " << (i + 1) << ": " << seq2[i] << "\n";
    }

    return 0;
}
